  // Technique detail info
  'techniques.box.detail': 'Navy SEALs \u0924\u0923\u093e\u0935 \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e\u092a\u0928\u093e\u0938\u093e\u0920\u0940 \u0935\u093e\u092a\u0930\u0924\u093e\u0924. \u0938\u092e\u093e\u0928 \u0936\u094d\u0935\u093e\u0938 \u0918\u0947\u0923\u0947, \u0927\u0930\u0923\u0947, \u0938\u094b\u0921\u0923\u0947 \u0906\u0923\u093f \u0927\u0930\u0923\u0947 \u0939\u0947 \u091f\u092a\u094d\u092a\u0947 \u0936\u093e\u0902\u0924 \u0932\u092f \u0924\u092f\u093e\u0930 \u0915\u0930\u0924\u093e\u0924 \u091c\u0940 \u0915\u0949\u0930\u094d\u091f\u093f\u0938\u0949\u0932 \u0915\u092e\u0940 \u0915\u0930\u0924\u0947 \u0906\u0923\u093f \u0932\u0915\u094d\u0937 \u0938\u0941\u0927\u093e\u0930\u0924\u0947.',
  'techniques.fourSevenEight.detail': '\u0921\u0949. \u0905\u0945\u0902\u0921\u094d\u0930\u094d\u092f\u0942 \u0935\u0947\u0932 \u092f\u093e\u0902\u0928\u0940 \u0935\u093f\u0915\u0938\u093f\u0924 \u0915\u0947\u0932\u0947. \u0926\u0940\u0930\u094d\u0918 \u0936\u094d\u0935\u093e\u0938 \u0938\u094b\u0921\u0923\u0947 \u092a\u0945\u0930\u093e\u0938\u093f\u092e\u094d\u092a\u0945\u0925\u0947\u091f\u093f\u0915 \u092e\u091c\u094d\u091c\u093e\u0938\u0902\u0938\u094d\u0925\u093e \u0938\u0915\u094d\u0930\u093f\u092f \u0915\u0930\u0924\u0947, \u092e\u094d\u0939\u0923\u0942\u0928 \u0915\u093e\u0939\u0940 \u092e\u093f\u0928\u093f\u091f\u093e\u0902\u0924 \u091d\u094b\u092a\u0923\u094d\u092f\u093e\u0938\u093e\u0920\u0940 \u0906\u0926\u0930\u094d\u0936.',
  'techniques.physioSigh.detail': 'Stanford \u0928\u094d\u092f\u0942\u0930\u094b\u0938\u093e\u092f\u0902\u091f\u093f\u0938\u094d\u091f \u0921\u0949. \u0905\u0945\u0902\u0921\u094d\u0930\u094d\u092f\u0942 \u0939\u0941\u092c\u0930\u092e\u0928 \u092f\u093e\u0902\u0928\u0940 \u0936\u094b\u0927\u0932\u0947. \u0926\u0941\u092a\u094d\u092a\u091f \u0936\u094d\u0935\u093e\u0938 \u0918\u0947\u0923\u0947 \u0928\u0902\u0924\u0930 \u0926\u0940\u0930\u094d\u0918 \u0936\u094d\u0935\u093e\u0938 \u0938\u094b\u0921\u0923\u0947 \u0939\u093e \u0930\u093f\u0905\u0932-\u091f\u093e\u0907\u092e\u092e\u0927\u094d\u092f\u0947 \u0924\u0923\u093e\u0935 \u0915\u092e\u0940 \u0915\u0930\u0923\u094d\u092f\u093e\u091a\u093e \u0938\u0930\u094d\u0935\u093e\u0924 \u091c\u0932\u0926 \u092e\u093e\u0930\u094d\u0917.',
  'techniques.coherence.detail': '\u092a\u094d\u0930\u0924\u093f \u092e\u093f\u0928\u093f\u091f 5.5 \u0936\u094d\u0935\u093e\u0938 \u0918\u0947\u0924\u0932\u094d\u092f\u093e\u0928\u0947 \u0939\u0943\u0926\u092f \u0917\u0924\u0940, \u0930\u0915\u094d\u0924\u0926\u093e\u092c \u0906\u0923\u093f \u092e\u091c\u094d\u091c\u093e\u0938\u0902\u0938\u094d\u0925\u093e \u0938\u092e\u0928\u094d\u0935\u092f\u093f\u0924 \u0939\u094b\u0924\u0947 \u2014 \u0907\u0937\u094d\u091f\u0924\u092e HRV \u0938\u093e\u0920\u0940 "\u0915\u094b\u0939\u0947\u0930\u0928\u094d\u0938" \u0928\u093e\u0935\u093e\u091a\u0940 \u0938\u094d\u0925\u093f\u0924\u0940 \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0939\u094b\u0924\u0947.',
  'techniques.triangle.detail': '\u0928\u0935\u0936\u093f\u0915\u094d\u092f\u093e\u0902\u0938\u093e\u0920\u0940 \u092f\u094b\u0917\u094d\u092f \u0905\u0938\u0932\u0947\u0932\u093e \u0938\u094c\u092e\u094d\u092f 3-\u091f\u092a\u094d\u092a\u094d\u092f\u093e\u0902\u091a\u093e \u092a\u0945\u091f\u0930\u094d\u0928. \u0936\u094d\u0935\u093e\u0938 \u0927\u0930\u0923\u094d\u092f\u093e\u0936\u093f\u0935\u093e\u092f \u092e\u091c\u094d\u091c\u093e\u0938\u0902\u0938\u094d\u0925\u093e \u0938\u0902\u0924\u0941\u0932\u093f\u0924 \u0915\u0930\u0924\u0947, \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915\u093e\u0938\u093e\u0920\u0940 \u0938\u094b\u092a\u0947 \u0906\u0923\u093f \u0938\u0941\u0932\u092d.',
  'techniques.power.detail': '\u090f\u0915 \u092a\u094d\u0930\u0917\u0924 \u0936\u094d\u0935\u093e\u0938\u094b\u091a\u094d\u091b\u094d\u0935\u093e\u0938 \u0924\u0902\u0924\u094d\u0930. \u091c\u0932\u0926 \u0936\u094d\u0935\u093e\u0938\u094b\u091a\u094d\u091b\u094d\u0935\u093e\u0938 \u0928\u0902\u0924\u0930 \u0936\u094d\u0935\u093e\u0938 \u0927\u0930\u0923\u0947 \u090a\u0930\u094d\u091c\u093e \u0935\u093e\u0922\u0935\u0924\u0947, \u0930\u0915\u094d\u0924 \u0915\u094d\u0937\u093e\u0930\u0940\u092f \u0915\u0930\u0924\u0947 \u0906\u0923\u093f \u0930\u094b\u0917\u092a\u094d\u0930\u0924\u093f\u0915\u093e\u0930\u0936\u0915\u094d\u0924\u0940 \u0935\u093e\u0922\u0935\u0924\u0947.',
  'techniques.fourFourSixTwo.detail': '\u0936\u094d\u0935\u093e\u0938 \u0918\u0947\u0923\u094d\u092f\u093e\u091a\u094d\u092f\u093e (4s) \u0924\u0941\u0932\u0928\u0947\u0924 \u0926\u0940\u0930\u094d\u0918 \u0936\u094d\u0935\u093e\u0938 \u0938\u094b\u0921\u0923\u0947 (6s) \u0936\u0930\u0940\u0930\u093e\u0932\u093e \u0916\u094b\u0932 \u0906\u0930\u093e\u092e\u093e\u0924 \u0928\u0947\u0924\u0947. \u091a\u0915\u094d\u0930\u093e\u0902\u0926\u0930\u092e\u094d\u092f\u093e\u0928\u091a\u093e \u0932\u0939\u093e\u0928 \u0935\u093f\u0930\u093e\u092e \u0936\u094d\u0935\u093e\u0938\u093e\u091a\u0940 \u0932\u092f \u092a\u0941\u0928\u094d\u0939\u093e \u0938\u0947\u091f \u0915\u0930\u0924\u094b.',
  'techniques.kapalabhati.detail': '\u092a\u094d\u0930\u093e\u091a\u0940\u0928 \u092f\u094b\u0917\u093f\u0915 \u0924\u0902\u0924\u094d\u0930 \u092e\u094d\u0939\u0923\u091c\u0947 "\u0915\u092a\u093e\u0932 \u092a\u094d\u0930\u0915\u093e\u0936\u093f\u0924 \u0936\u094d\u0935\u093e\u0938." \u091c\u0932\u0926 \u091c\u094b\u0930\u0926\u093e\u0930 \u0936\u094d\u0935\u093e\u0938 \u0938\u094b\u0921\u0923\u0947 \u0936\u0930\u0940\u0930\u093e\u0932\u093e \u090a\u0930\u094d\u091c\u093e \u0926\u0947\u0924\u0947, \u092e\u0928 \u0938\u094d\u0935\u091a\u094d\u091b \u0915\u0930\u0924\u0947 \u0906\u0923\u093f \u0921\u093e\u092f\u093e\u092b\u094d\u0930\u093e\u092e \u092e\u091c\u092c\u0942\u0924 \u0915\u0930\u0924\u0947.',
  'techniques.twoToOne.detail': '\u0936\u094d\u0935\u093e\u0938 \u0938\u094b\u0921\u0923\u0947 \u0936\u094d\u0935\u093e\u0938 \u0918\u0947\u0923\u094d\u092f\u093e\u092a\u0947\u0915\u094d\u0937\u093e \u0926\u0941\u092a\u094d\u092a\u091f \u0932\u093e\u0902\u092c\u0940\u091a\u0947 \u0905\u0938\u0924\u0947, CO\u2082 \u0938\u094b\u0921\u0923\u0947 \u091c\u093e\u0938\u094d\u0924\u0940\u0924 \u091c\u093e\u0938\u094d\u0924 \u0915\u0930\u0924\u0947 \u0906\u0923\u093f \u0935\u0947\u0917\u0938 \u092e\u091c\u094d\u091c\u093e\u0924\u0902\u0924\u0942 \u0938\u0915\u094d\u0930\u093f\u092f \u0915\u0930\u0924\u0947. \u0916\u094b\u0932 \u0906\u0930\u093e\u092e\u093e\u0938\u093e\u0920\u0940 \u0938\u0930\u094d\u0935\u093e\u0924 \u092a\u094d\u0930\u092d\u093e\u0935\u0940 \u092a\u0945\u091f\u0930\u094d\u0928\u092a\u0948\u0915\u0940 \u090f\u0915.',
  'techniques.cyclicSigh.detail': 'Stanford \u0905\u092d\u094d\u092f\u093e\u0938\u093e\u0928\u0947 \u0926\u093e\u0916\u0935\u0932\u0947 \u0915\u0940 5 \u092e\u093f\u0928\u093f\u091f\u093e\u0902\u091a\u0947 \u091a\u0915\u094d\u0930\u0940\u092f \u0909\u0938\u093e\u0938\u0947 \u0924\u0923\u093e\u0935 \u0915\u092e\u0940 \u0915\u0930\u0923\u094d\u092f\u093e\u0924 \u0927\u094d\u092f\u093e\u0928\u093e\u092a\u0947\u0915\u094d\u0937\u093e \u0905\u0927\u093f\u0915 \u092a\u094d\u0930\u092d\u093e\u0935\u0940 \u0906\u0939\u0947. \u0926\u0941\u092a\u094d\u092a\u091f \u0936\u094d\u0935\u093e\u0938 \u0918\u0947\u0923\u0947 + \u0926\u0940\u0930\u094d\u0918 \u0936\u094d\u0935\u093e\u0938 \u0938\u094b\u0921\u0923\u0947 \u092e\u091c\u094d\u091c\u093e\u0938\u0902\u0938\u094d\u0925\u093e \u092a\u0941\u0928\u094d\u0939\u093e \u0938\u0947\u091f \u0915\u0930\u0924\u0947.',

